 990→	filesTouched := []string{"main.go"}
 991→
 992→	// PromptAttribution captured that user added 5 lines between checkpoints
 993→	promptAttributions := []PromptAttribution{
 994→		{
 995→			CheckpointNumber: 2,
 996→			UserLinesAdded:   5,
 997→			UserLinesRemoved: 0,
 998→			UserAddedPerFile: map[string]int{"main.go": 5}, // KEY: per-file tracking
 999→		},
1000→	}
1001→
1002→	result := CalculateAttributionWithAccumulated(
1003→		baseTree, shadowTree, headTree, filesTouched, promptAttributions,
1004→	)
1005→
1006→	if result == nil {
1007→		t.Fatal("expected non-nil result")
1008→	}
1009→
1010→	// Expected calculation with per-file tracking:
1011→	// - base → shadow: 15 lines added (10 agent + 5 user)
1012→	// - accumulatedUserAdded: 5 (from PromptAttribution)
1013→	// - totalAgentAdded: 15 - 5 = 10
1014→	// - shadow → head: +3 lines added, -3 lines removed (user modification)
1015→	// - totalUserAdded: 5 + 3 = 8
1016→	// - totalUserRemoved: 3
1017→	// - totalHumanModified: min(8, 3) = 3
1018→	// - userSelfModified: min(3 removed from main.go, 5 user added to main.go) = 3
1019→	// - humanModifiedAgent: 3 - 3 = 0 (no agent lines were modified!)
1020→	// - agentLinesInCommit: 10 - 0 - 0 = 10 (CORRECT: agent lines unchanged)
1021→	// - Total: 10 + 5 = 15
1022→	// - Agent percentage: 10/15 = 66.7%
1023→
1024→	t.Logf("Attribution: agent=%d, human_added=%d, human_modified=%d, total=%d, percentage=%.1f%%",
1025→		result.AgentLines, result.HumanAdded, result.HumanModified, result.TotalCommitted, result.AgentPercentage)
1026→
