1029→	}
1030→	if result.HumanAdded != 5 {
1031→		t.Errorf("HumanAdded = %d, want 5 (8 total - 3 modifications)", result.HumanAdded)
1032→	}
1033→	if result.HumanModified != 3 {
1034→		t.Errorf("HumanModified = %d, want 3 (total modifications for reporting)", result.HumanModified)
1035→	}
1036→	if result.TotalCommitted != 15 {
